	if(FAILED(D3DXCreateFontIndirect(m_pDevice, &FontInfo, &m_pFont)))
	{
		ERR_MSG(TEXT("Create Font Fail"));

		return E_FAIL;
	}

	if(FAILED(D3DXCreateLine(m_pDevice, &m_pLine)))
	{
		ERR_MSG(TEXT("Create Line Fail"));

		return E_FAIL;
	}

	//»ç¿îµå µð¹ÙÀÌ½º »ý¼º
